sp_widget.client_script:
function ($timeout) {
  var c = this;


function drawGauge(data) {
  var canvas = document.getElementById('gaugeCanvas');
  if (!canvas) return;

  var ctx = canvas.getContext('2d');
  var width = canvas.width;
  var height = canvas.height;

  ctx.clearRect(0, 0, width, height);

  var centerX = width / 2;
  var centerY = height * 0.75; // Antes estava 0.9 — subimos um pouco
  var radius = 100;

  function percentToAngle(p) {
    return Math.PI * (1 + p / 100);
  }

  function drawArc(startPercent, endPercent, color) {
    ctx.beginPath();
    ctx.arc(
      centerX, centerY, radius,
      percentToAngle(startPercent),
      percentToAngle(endPercent),
      false
    );
    ctx.lineWidth = 30;
    ctx.strokeStyle = color;
    ctx.stroke();
  }

  drawArc(0, data.limiteAlerta, '#62bf46');         // verde
  drawArc(data.limiteAlerta, data.limitePrudencial, '#f7e821'); // amarelo
  drawArc(data.limitePrudencial, data.limiteMaximo, '#ff4513'); // vermelho

  // Ponteiro - mais curto e centralizado
  var ponteiroAngle = percentToAngle(data.comprometimento);
  ctx.beginPath();
  ctx.moveTo(centerX, centerY);
  ctx.lineTo(
    centerX + radius * 0.7 * Math.cos(ponteiroAngle),
    centerY + radius * 0.7 * Math.sin(ponteiroAngle)
  );
  ctx.lineWidth = 8;
  ctx.strokeStyle = '#555';
  ctx.stroke();

  // Valor central
  ctx.font = "bold 22px Arial";
  ctx.fillStyle = "#000";
  ctx.textAlign = "center";
  ctx.fillText(data.comprometimento + "%", centerX, centerY - 20);

  // Texto da legenda
  ctx.font = "14px Arial";
  ctx.fillText("Comprometimento RCL com Pessoal", centerX, centerY - 40);

  // Rótulos dos limites com bom espaçamento
  ctx.font = "12px Arial";
  ctx.fillText("Limite de Alerta", centerX - radius + 10, centerY + 20);
  ctx.fillText(data.limiteAlerta + "%", centerX - radius + 10, centerY + 35);

  ctx.fillText("Limite Prudencial", centerX, centerY - radius - 10);
  ctx.fillText(data.limitePrudencial + "%", centerX, centerY - radius + 5);

  ctx.fillText("Limite Máximo", centerX + radius - 10, centerY + 20);
  ctx.fillText(data.limiteMaximo + "%", centerX + radius - 10, centerY + 35);
}








  $timeout(function () {
    if (c.data && !c.data.error) {
      drawGauge(c.data);
    }
  }, 0);
}

sp_widget.css:
.report-widget {
  border-radius: 12px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08);
  background-color: #fff;
  margin-top: 24px;
  overflow: hidden;
  min-height: 400px;
  max-height: 600px;

  display: flex;
  flex-direction: column;
}

.panel-heading {
  background-color: #f6f8fa;
  padding: 12px 16px;
  border-bottom: 1px solid #e1e4e8;
  border-top-left-radius: 12px;
  border-top-right-radius: 12px;
}

.panel-title {
  margin: 0;
  font-size: 18px;
  color: #333;
}

.panel-body {
  padding: 16px;
  flex: 1;
  width: 100%;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.report-summary {
  display: flex;
  align-items: center;
  margin-bottom: 16px;
}

.report-icon {
  font-size: 32px;
  color: #4a90e2;
  margin-right: 12px;
}

.report-value {
  font-size: 28px;
  font-weight: bold;
  color: #2c3e50;
}

.report-label {
  font-size: 14px;
  color: #7f8c8d;
}

.chart-container {
  width: 100%;
  height: 100%;
  flex: 1;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 250px;
}

canvas {
  width: 100% !important;
  height: auto !important;
  min-height: 200px;
  max-height: 300px;
}

.error-message {
  color: red;
  text-align: center;
  margin-top: 12px;
  font-weight: bold;
}

sp_widget.script:
(function() {
    var anoAtual = new GlideDateTime().getYearUTC();

    var gr = new GlideRecord('x_sded9_portal_t_0_u_despesa_pessoal');
    gr.addQuery('u_ano', 2023);
    gr.orderByDesc('sys_created_on'); // Caso tenha mais de uma linha para o mesmo ano, pegar a mais recente
    gr.query();

    if (gr.next()) {
        data.comprometimento = parseFloat(gr.u_comprometimento_rcl.toString());
        data.limiteAlerta = parseFloat(gr.u_limite_de_alerta.toString());
        data.limitePrudencial = parseFloat(gr.u_limite_prudencial.toString());
        data.limiteMaximo = parseFloat(gr.u_limite_maximo.toString());
        data.ano = gr.u_ano.toString();
        // Pode incluir mais campos conforme necessidade
    } else {
        data.error = "Nenhum dado encontrado para o ano " + anoAtual;
    }
})();
